        this.scriptId = event.getScriptId();
        this.arguments = event.getScriptEvent().getArguments();
        this.scriptEvent = event.getScriptEvent();
    }

    @Override
    public String toString() {
        String scriptDebug = "SCRIPT FIRED | script id: " + scriptId;
		try {
